Author: <a href data-email-masked rel="nofollow">stigl...@hotmail.com</a><br>Date: Fri Feb  8 13:32:22 2008<br>New Revision: 118<p>Added:<br>   trunk/tsDyn/R/TVECM.r   (contents, props changed)<p>Log:<br>Function TVECM<p>Added: trunk/tsDyn/R/TVECM.r<br>==============================================================================<br>--- (empty file)<br>+++ trunk/tsDyn/R/TVECM.r	Fri Feb  8 13:32:22 2008<br>@@ -0,0 +1,518 @@<br>+TVECM&lt;-function(data,lag=1,trend=TRUE, bn=50, ngridG=50, trim=0.05, <br>nthresh=1,plot=TRUE, dummyToBothRegimes=TRUE, methodMapply=FALSE, <br>gamma1=list(exact=NULL, int=c(&quot;from&quot;,&quot;to&quot;), <br>around=&quot;val&quot;),gamma2=list(exact=NULL, int=c(&quot;from&quot;,&quot;to&quot;), <br>around=&quot;val&quot;), beta=list(exact=NULL, int=c(&quot;from&quot;,&quot;to&quot;), <br>around=c(&quot;val&quot;,&quot;by&quot;)), rest=c(&quot;none&quot;, &quot;equal&quot;, &quot;signOp&quot;), <br>model=c(&quot;All&quot;, &quot;only_ECT&quot;) ) {<br>+y&lt;-as.matrix(data)<br>+T&lt;-nrow(y)		#T: number of observations<br>+p&lt;-lag 		#p: Number of lags<br>+k&lt;-ncol(y) 		#k: Number of equations<br>+if(k&gt;2 &amp; is.null(beta$exact)) {stop(&quot;Sorry, the search is only <br>possible with two variables. If more, please provide pre-specified beta values&quot;)}<br>+if(is.null(colnames(data))==TRUE){colnames(data)&lt;-paste(&quot;Var&quot;, c(1:k), sep=&quot;&quot;)}<br>+<br>+model&lt;-match.arg(model)<br>+model&lt;-switch(model, &quot;All&quot;=&quot;All&quot;, &quot;only_ECT&quot;=&quot;only_ECT&quot;)<br>+<br>+ysmall&lt;-y[(p+1):T,]<br>+DeltaY&lt;-diff(y)[(p+1):(T-1),]<br>+Xminus1&lt;-embed(y,p+2)[,(k+1):(k+k)]<br>+DeltaX&lt;-embed(diff(y),p+1)[,-(1:k)]<br>+if(trend==TRUE){DeltaX&lt;-cbind(rep(1,T-p-1), DeltaX)}<br>+<br>+##Long-run relationship OLS estimation<br>+coint&lt;-lm(y[,1]~ -1 +y[,2]) #Relation cointégrante estimée par OLS<br>+<br>+betaLT&lt;-coint$coef<br>+betaLT_std &lt;- sqrt(diag(summary(coint)$sigma*summary(coint)$cov))<br>+<br>+ECT&lt;-y%*%c(1,-betaLT)<br>+#ECTminus1&lt;-ECT[-c(1:p,T)]<br>+ECTminus1&lt;-Xminus1%*%c(1,-betaLT)<br>+<br>+ECM&lt;-residuals(coint)<br>+ECMminus1&lt;-ECM[-c(1:p,T)]<br>+<br>+##Linear VECM estimation (Engle-Granger two step approach)<br>+Z&lt;-cbind(ECTminus1,DeltaX)		#Z: All regressors,ECT, trend and lags <br>dim: t x npar<br>+Y&lt;-DeltaY				#Y: Delta Y, dim t x 2<br>+<br>+B&lt;-t(Y)%*%Z%*%solve(t(Z)%*%Z)		#B: OLS parameters, dim 2 x npar<br>+npar&lt;-ncol(B)<br>+<br>+rownames(B)&lt;-paste(&quot;Equation&quot;,colnames(data))<br>+if(trend==TRUE){colnames(B)&lt;-c(&quot;ECM&quot;,&quot;Intercept&quot;,c(paste(rep(colnames(data),p), <br>-rep(1:p, each=k))))}<br>+else {colnames(B)&lt;-c(&quot;ECM&quot;,c(paste(rep(colnames(data),p), -rep(1:p, <br>each=k)))) }<br>+<br>+res&lt;-Y-Z%*%t(B)<br>+<br>+Sigma&lt;- matrix(crossprod(res), nrow=k,dimnames=list(colnames(data), colnames(data)))<br>+nlike&lt;-log(det(Sigma))/(T-p-1)		#	nlike=(t/2)*log(det(sige));<br>+aic&lt;-nlike+2*(npar)/(T-p-1)	<br>+bic&lt;-nlike+log(T-p-1)*(npar)/(T-p-1)	#bic #=nlike+log10(t)*4*(1+k); ###BIC<br>+<br>+###Output for linear VECM<br>+cat(&quot;Size of full sample:&quot;, T)<br>+cat(&quot;
