&quot;)<br>+<br>+<br>+#########################<br>+###Set up of the grid<br>+#########################<br>+<br>+#Function to select values around a given point<br>+aroundGrid &lt;- function(around,allvalues,ngrid,trim){<br>+	ng &lt;- length(allvalues)<br>+	wh.around &lt;- which(allvalues==around)<br>+	if(length(wh.around)==0)<br>+		stop(&quot;
Sorry, the value you gave for the around argument did not match&quot;)<br>+	if(length(wh.around)&gt;1){<br>+		warning(&quot;
There were&quot;, length(wh.around),&quot; values corresponding to <br>the around argument. The first one was taken&quot;)<br>+		wh.around&lt;-wh.around[1]}<br>+	ar &lt;- seq(from=wh.around-round(ngrid/2),  <br>to=(wh.around+round(ngrid/2)))		#Values around the point<br>+	ar2 &lt;- ar[ar&gt;=round(trim*ng)&amp;ar&lt;=round((1-trim)*ng)]			#Bounding with trim<br>+	values &lt;- allvalues[ar2]<br>+	return(values)<br>+}<br>+<br>+<br>+###grid for gamma1<br>+allgammas&lt;-sort(unique(ECM))<br>+ng&lt;-length(allgammas)<br>+<br>+#Default method: grid from lower to higher point<br>+gammas&lt;-allgammas[round(seq(from=trim, to=1-trim, length.out=ngridG)*ng)]<br>+#gamma pre-specified<br>+if(is.null(gamma1$exact)==FALSE){<br>+	if(any(allgammas==gamma1$exact)==FALSE)<br>+		warning(&quot;The value you gave for gamma does not correspond to an <br>existing value. This causes problems currently&quot;)<br>+	gammas&lt;-gamma1$exact<br>+	ngridG&lt;-1<br>+	}<br>+#interval to search between given by user<br>+if(is.numeric(gamma1$int)){<br>+	intDown&lt;-which(round(allgammas,3)==round(gamma1$int[1],3))<br>+	intUp&lt;-which(round(allgammas,3)==round(gamma1$int[2],3))<br>+	gammas&lt;-allgammas[seq(from=intDown, to=intUp, length.out=ngridG)]<br>+	}<br>+#value to search around	given by user<br>+if(is.numeric(gamma1$around))		<br>+	gammas&lt;-aroundGrid(gamma$around,allvalues=allgammas,ngridG,trim)<br>+<br>+<br>+###Grid for beta<br>+#Default method: interval to search based on confidnce interval from <br>linear model<br>+betas&lt;- seq(from=betaLT -2*betaLT_std, to=betaLT +2*betaLT_std, length.out=bn)<br>+#beta pre-specified<br>+if(is.null(beta$exact)==FALSE)			<br>+	{betas&lt;-beta$exact; bn&lt;-1}<br>+#interval to search between given by user<br>+if(is.numeric(beta$int))			<br>+	betas&lt;-seq(from=beta$int[1], to=beta$int[2], length.out=bn)<br>+#value to search around	given by user<br>+if(is.numeric(beta$around)){<br>+	by&lt;-beta$around[2]<br>+	betas&lt;-seq(from=beta$around[1]-bn*by/2, to=beta$around[1]+bn*by/2, by=by)<br>+	}<br>+<br>+################<br>+####One threshold model<br>+################<br>+<br>+oneSearch&lt;-function(betas, gammas){<br>+<br>+###Search function<br>+<br>+#New operator if the dummy apply to both regimes. Is made outside the <br>function so is evaluated only once<br>+#dummy&lt;-match.arg(dummy, &quot;both regimes&quot;=&quot;both regimes&quot;, &quot;only one <br>regime&quot;=&quot;only one regime&quot;)<br>+if(dummyToBothRegimes==TRUE){&quot;%a%&quot;&lt;-function(matrix,dummy) matrix*dummy}<br>+else {&quot;%a%&quot;&lt;-function(matrix,dummy) matrix}<br>+<br>+oneThresh&lt;-function(betai, gam, Y, Xminus1,DeltaX){<br>+	ECTi&lt;-Xminus1%*%c(1,-betai)	#ECT in a column<br>+	zi&lt;-cbind(ECTi,DeltaX)		#All variables: ECT and lag, of dim t x kp+1+1<br>+	d1&lt;-ifelse(ECTi&lt;=gam, 1,0)	#Dummy vector 		#d1=(w&lt;=gam);<br>+	n1&lt;-mean(d1)			#Number of elements of the ECT under the threshold<br>+	if(<a href="http://is.na" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://is.na&amp;source=gmail&amp;ust=1792465582101000&amp;usg=AOvVaw1Px1JZ_DHgwarlPrcLrhZp">is.na</a>(n1)==TRUE) n1&lt;-0<br>+	if (min(n1,1-n1)&gt;trim) {<br>+		zigamma&lt;-c(d1)*zi<br>+		zi&lt;-zi%a%c(1-d1)		#new operator for choice between set up of first matrix<br>+		Z&lt;-cbind(zigamma,zi)<br>+		LS&lt;-crossprod(c(Y-tcrossprod(Z,crossprod(Y,Z)%*%solve(crossprod(Z)))))<br>+		}<br>+	else LS&lt;-NA<br>+	return(LS)<br>+}#end function oneThresh<br>+<br>+<br>+###Grid search<br>+<br>+<br>+####Method with for<br>+if(methodMapply==FALSE){<br>+<br>+store&lt;-matrix(NA,nrow=length(gammas), ncol=length(betas))	<br>+<br>+for (i in seq_len(length(gammas))){<br>+   gam&lt;-gammas[i]<br>+    for (j in seq_len(length(betas))){<br>+	betai&lt;-betas[j]<br>+	store[i,j]&lt;-oneThresh(betai=betai, gam=gam, DeltaX=DeltaX, Xminus1=Xminus1,Y=Y)<br>+	}<br>+}<br>+<br>+#m&lt;-min(store, na.rm=TRUE)<br>+na&lt;-sum(ifelse(<a href="http://is.na" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://is.na&amp;source=gmail&amp;ust=1792465582101000&amp;usg=AOvVaw1Px1JZ_DHgwarlPrcLrhZp">is.na</a>(store),1,0))<br>+if(na&gt;0) cat(&quot;
&quot;,na, &quot; points of the grid lead to regimes with <br>percentage of observations &lt; trim and were not computed
&quot;)<br>+<br>+<br>+pos&lt;-which(store==min(store, na.rm=TRUE), arr.ind=TRUE)		#Best gamma<br>+if(nrow(pos)&gt;1) {<br>+	warning(&quot;There were &quot;,nrow(pos), &quot; thresholds values which minimize <br>the SSR in the first search, the first one was taken&quot;) 	<br>+	pos&lt;-pos[,1]}<br>+<br>+bestGamma1&lt;-gammas[pos[1]]<br>+beta_grid&lt;-betas[pos[2]]<br>+<br>+} #end methodMapply false<br>+###Method with mapply<br>+<br>+if(methodMapply==TRUE){<br>+grid&lt;-expand.grid(betas,gammas)<br>+oneThreshTemp&lt;-function(betai,gam) oneThresh(betai=betai, gam=gam, <br>DeltaX=DeltaX,Xminus1=Xminus1, Y=Y)<br>+storemap&lt;-mapply(oneThreshTemp, betai=grid[,1], gam=grid[,2])<br>+bests&lt;-which(storemap==min(storemap, na.rm=TRUE))<br>+if(length(bests)&gt;1) {<br>+	warning(&quot;There were &quot;,length(bests), &quot; thresholds values which <br>minimize the SSR in the first search, the first one was taken&quot;) 	<br>+	bests&lt;-bests[1]}<br>+beta_grid&lt;-grid[bests,1]<br>+bestGamma1&lt;-grid[bests,2]<br>+}<br>+<br>+<br>+<br>+gammaMLE&lt;-0.02321329<br>+betaMLE&lt;-0.8916303<br>+<br>+#bestGamma1&lt;-gammaMLE<br>+#beta_grid&lt;-betaMLE<br>+<br>+###Plot results of grid search<br>+if(is.null(gamma1$exact)==FALSE&amp;is.null(beta$exact)==FALSE){plot&lt;-FALSE}<br>+<br>+if(plot==TRUE){<br>+if(is.null(beta$exact)==FALSE&amp;is.null(gamma1$exact)==TRUE){<br>+	plot(gammas,store, type=&quot;l&quot;, xlab=&quot;Threshold parameter gamma&quot;, <br>ylab=&quot;Residual Sum of Squares&quot;, main=&quot;Grid Search&quot;)}<br>+if(is.null(beta$exact)==TRUE&amp;is.null(gamma1$exact)==FALSE){<br>+	plot(betas,store, type=&quot;l&quot;, xlab=&quot;Cointegrating parameter beta&quot;, <br>ylab=&quot;Residual Sum of Squares&quot;, main=&quot;Grid Search&quot;)}<br>+if(is.null(beta$exact)==TRUE&amp;is.null(gamma1$exact)==TRUE){<br>+	betaRSS&lt;-apply(store,2,FUN=min, na.rm=TRUE)<br>+	gammaRSS&lt;-apply(store,1,FUN=min, na.rm=TRUE)<br>+	layout(c(1,2))<br>+	plot(gammas,gammaRSS, type=&quot;l&quot;, xlab=&quot;Threshold parameter gamma&quot;, <br>ylab=&quot;Residual Sum of Squares&quot;, main=&quot;Grid Search&quot;)<br>+	plot(betas,betaRSS, type=&quot;l&quot;, xlab=&quot;Cointegrating parameter beta&quot;, <br>ylab=&quot;Residual Sum of Squares&quot;)<br>+	abline(v=betaLT, lty=3)<br>+	legend(&quot;topright&quot;, &quot;OLS estimate from linear VECM&quot;, lty=3)}<br>+}#end of the plot<br>+<br>+#result of the whole function to search for one threshold<br>+list(beta=beta_grid, gamma=bestGamma1)<br>+}	#end of function oneSearch<br>+<br>+if(nthresh==1){<br>+results&lt;-oneSearch(betas, gammas)<br>+bestBeta&lt;-results$beta<br>+bestThresh&lt;-results$gamma<br>+}#end of if nthresh=1<br>+############################<br>+###Search for two thresholds<br>+############################<br>+<br>+###Two thresholds model: all variables change, three ECT<br>+<br>+if(nthresh==2){<br>+<br>+<br>+two_Thresh&lt;-function(betai,gam1,gam2){<br>+	ECTi&lt;-Xminus1%*%c(1,-betai)	#ECT in a column<br>+	zi&lt;-cbind(ECTi,DeltaX)		#All variables: ECT and lag<br>+	d1&lt;-ifelse(ECTi&lt;=gam1, 1,0)	#Dummy vector<br>+	n1&lt;-mean(d1)			#Number of elements of the ECT under the threshold<br>+	d2&lt;-ifelse(ECTi&gt;gam2,1,0)<br>+	n2&lt;-mean(d2)<br>+	if(<a href="http://is.na" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://is.na&amp;source=gmail&amp;ust=1792465582101000&amp;usg=AOvVaw1Px1JZ_DHgwarlPrcLrhZp">is.na</a>(n1)==TRUE) {n1&lt;-0; n2&lt;-0}<br>+	if (min(n1,n2,1-n1-n2)&gt;trim) {<br>+		ziUnder&lt;-c(d1)*zi<br>+		ziOver&lt;-c(d2)*zi<br>+		ziMiddle&lt;-c(1-d1-d2)*zi<br>+		Z&lt;-cbind(ziUnder,ziMiddle,ziOver)<br>+		LS&lt;-crossprod(c(Y-tcrossprod(Z,crossprod(Y,Z)%*%solve(crossprod(Z)))))<br>+		}<br>+	else LS&lt;-NA<br>+<br>+	return(LS)<br>+}<br>+<br>+###Two thresholds model: only ECT change (and is zero in the middle regime)<br>+<br>+two_partial_Thresh&lt;-function(betai,gam1,gam2){<br>+	ECTi&lt;-Xminus1%*%c(1,-betai)	#ECT in a column<br>+	d1&lt;-ifelse(ECTi&lt;=gam1, 1,0)	#Dummy vector<br>+	n1&lt;-mean(d1)			#Number of elements of the ECT under the threshold<br>+	d2&lt;-ifelse(ECTi&gt;gam2,1,0)<br>+	n2&lt;-mean(d2)<br>+	if(<a href="http://is.na" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://is.na&amp;source=gmail&amp;ust=1792465582101000&amp;usg=AOvVaw1Px1JZ_DHgwarlPrcLrhZp">is.na</a>(n1)==TRUE) {n1&lt;-0; n2&lt;-0}<br>+	if (min(n1,n2,1-n1-n2)&gt;trim) {<br>+		ectUnder&lt;-c(d1)*ECTi<br>+		ectOver&lt;-c(d2)*ECTi<br>+		Z&lt;-cbind(ectUnder,ectOver,DeltaX)<br>+		result&lt;-crossprod(c(Y-tcrossprod(Z,crossprod(Y,Z)%*%solve(crossprod(Z)))))<br>+		}<br>+	else result&lt;-NA<br>+<br>+	return(result)<br>+}#end two partial thresh<br>+<br>+###Conditional search<br>+<br>+<br>+###Conditionnal step<br>+bestone &lt;- oneSearch(betas, gammas)<br>+bestThresh &lt;- bestone$gamma<br>+bestBeta &lt;- bestone$beta<br>+func&lt;-switch(model, &quot;All&quot;=two_Thresh, &quot;only_ECT&quot;=two_partial_Thresh)<br>+<br>+cat(&quot;
Best threshold from first search&quot;, bestThresh)<br>+<br>+if(!is.null(gamma2$exact))<br>+	secondBestThresh&lt;-gamma2$exact<br>+<br>+if(is.null(gamma2$exact) &amp; !is.numeric(gamma2$around)){<br>+<br>+<br>+wh.thresh &lt;- which(allgammas==bestThresh)<br>+ninter&lt;-round(trim*nrow(Xminus1))<br>+<br>+#search for a second threshold smaller than the first<br>+if(wh.thresh&gt;2*ninter){<br>+	gammaMinus&lt;-allgammas[seq(from=ninter, to=wh.thresh-ninter)]<br>+	storeMinus &lt;- mapply(func,betai=bestBeta, gam1=gammaMinus,gam2=bestThresh)	<br>+}<br>+else	storeMinus &lt;- NA<br>+<br>+#search for a second threshold higher than the first<br>+if(length(wh.thresh&lt;length(allgammas)-2*ninter)){<br>+	gammaPlus&lt;-allgammas[seq(from=wh.thresh+ninter, to=length(allgammas)-ninter)]<br>+	storePlus &lt;- mapply(func,betai=bestBeta, gam1=bestThresh,gam2=gammaPlus)<br>+}<br>+else	storePlus &lt;- NA<br>+<br>+#results<br>+store2 &lt;- c(storeMinus, storePlus)<br>+positionSecond &lt;- which(store2==min(store2, na.rm=TRUE))<br>+if(length(positionSecond)&gt;1) warning(&quot;There <br>were &quot;,length(positionSecond), &quot; thresholds values which minimize the <br>SSR in the conditional step, the first one was taken&quot;)<br>+positionSecond&lt;-positionSecond[1]<br>+if(positionSecond&lt;=length(storeMinus)){secondBestThresh&lt;-gammaMinus[positionSecond]}<br>+else {secondBestThresh&lt;-gammaPlus[positionSecond-length(storeMinus)]}<br>+<br>+cat(&quot;
